```go
package cart

import "errors"

var (
	ErrItemNotFound = errors.New("item not found")
	ErrEmptyCart    = errors.New("cart is empty")
)

type Item struct {
	ID       string
	Name     string
	Price    float64
	Quantity int
}

type ShoppingCart struct {
	items map[string]*Item
}

func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items: make(map[string]*Item),
	}
}

func (c *ShoppingCart) AddItem(item Item) {
	if existing, ok := c.items[item.ID]; ok {
		existing.Quantity += item.Quantity
	} else {
		copyItem := item
		c.items[item.ID] = &copyItem
	}
}

func (c *ShoppingCart) RemoveItem(id string) error {
	if _, ok := c.items[id]; !ok {
		return ErrItemNotFound
	}
	delete(c.items, id)
	return nil
}

func (c *ShoppingCart) UpdateQuantity(id string, quantity int) error {
	item, ok := c.items[id]
	if !ok {
		return ErrItemNotFound
	}
	if quantity <= 0 {
		delete(c.items, id)
	} else {
		item.Quantity = quantity
	}
	return nil
}

func (c *ShoppingCart) GetItem(id string) (*Item, error) {
	item, ok := c.items[id]
	if !ok {
		return nil, ErrItemNotFound
	}
	return item, nil
}

func (c *ShoppingCart) GetItems() []Item {
	result := make([]Item, 0, len(c.items))
	for _, item := range c.items {
		result = append(result, *item)
	}
	return result
}

func (c *ShoppingCart) Total() float64 {
	var total float64
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total
}

func (c *ShoppingCart) Clear() {
	c.items = make(map[string]*Item)
}

func (c *ShoppingCart) ItemCount() int {
	var count int
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}

func (c *ShoppingCart) IsEmpty() bool {
	return len(c.items) == 0
}

func (c *ShoppingCart) ApplyDiscount(percent float64) float64 {
	total := c.Total()
	return total * (1 - percent/100)
}
```

